using System.Xml.Serialization;
namespace Clc.Polaris.Api.UnitTests.Models { [TestClass][UnitTest] public sealed class BibsPostResultXmlDeserializationTests { [TestMethod] public void Deserialize_Success() { var r = Deserialize<BibsPostResult>("<BibsPostResult><PAPIErrorCode>0</PAPIErrorCode><ImportJobID>123</ImportJobID></BibsPostResult>"); Assert.AreEqual(0, r.PAPIErrorCode); Assert.AreEqual(123, r.ImportJobID); } [TestMethod] public void Deserialize_Failure() { var r = Deserialize<BibsPostResult>("<BibsPostResult><PAPIErrorCode>1</PAPIErrorCode><ErrorMessage>bad</ErrorMessage></BibsPostResult>"); Assert.AreEqual(1, r.PAPIErrorCode); Assert.AreEqual("bad", r.ErrorMessage); } private static T Deserialize<T>(string xml) { using var reader = new StringReader(xml); return (T)new XmlSerializer(typeof(T)).Deserialize(reader)!; } } }
